const src = $('Boucle factures').first().json;
const j = $input.first() ? ($input.first().json || {}) : {};
let texte = '';
if (typeof j.content === 'string') texte = j.content;
else if (Array.isArray(j.content)) texte = j.content.map(c => (c && c.text) || '').join('');
else if (typeof j.text === 'string') texte = j.text;
else if (typeof j.output === 'string') texte = j.output;
else texte = JSON.stringify(j);
let d = null; let statut = 'ok';
try { const t = texte.replace(/```json|```/g, ''); d = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { statut = 'erreur_lecture'; d = {}; }
if (statut === 'ok' && (d.est_facture_fournisseur === false || d.est_facture_hac === false)) statut = 'pas_facture_fournisseur';
if (statut === 'ok' && d.type_doc === 'avoir') statut = 'avoir';
const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? '' : Number(v);
const quand = $now.setZone('Europe/Paris').toFormat('yyyy-LL-dd HH:mm');
const fourn = d.fournisseur && d.fournisseur !== 'autre' ? d.fournisseur : (/econology/i.test(src.nom_fichier) ? 'Econology' : 'HAC');
const base = { fournisseur: fourn, date_facture: d.date_facture || '', numero_facture: d.numero_facture ? "'" + d.numero_facture : '', lien_pdf: src.lien_pdf, file_id: src.file_id, traite_le: quand };
const REF_FRAIS = ['DEEE', 'ECO', 'FF', 'PORT'];
const estFrais = l => { const r = String(l.reference || '').trim().toUpperCase(); const des = String(l.designation || '').toLowerCase(); return l.categorie === 'frais' || REF_FRAIS.includes(r) || /transport|frais de port|port |livraison|eco.?contribution|eco.?participation|deee|frais de facturation|^f\.f/.test(des); };
const lignes = (statut === 'ok' && Array.isArray(d.lignes)) ? d.lignes.filter(l => !estFrais(l)) : [];
if (!lignes.length) return [{ json: Object.assign({ reference: '', designation: src.nom_fichier, categorie: '', quantite: '', prix_unitaire_net_ht: '', remise_pct: '', statut: statut === 'ok' ? 'aucune_ligne' : statut }, base) }];
return lignes.map(l => ({ json: Object.assign({ reference: l.reference ? "'" + String(l.reference).trim() : '', designation: String(l.designation || '').slice(0, 300), categorie: l.categorie || '', quantite: num(l.quantite), prix_unitaire_net_ht: num(l.prix_unitaire_net_ht), remise_pct: num(l.remise_pct), statut: 'ok' }, base) }));

const LOT = Number($('Parametres').first().json.lot) || 40;
const deja = new Set($('Lire prix').all().map(i => String(i.json.file_id || '').trim()).filter(Boolean));
const vus = new Set();
const fichiers = [];
for (const page of $('Lister factures fournisseurs').all()) for (const f of (page.json.files || [])) { if (!vus.has(f.id)) { vus.add(f.id); fichiers.push(f); } }
const aFaire = fichiers.filter(f => !deja.has(f.id)).sort((a, b) => String(a.createdTime).localeCompare(String(b.createdTime)));
return aFaire.slice(0, LOT).map(f => ({ json: { file_id: f.id, nom_fichier: f.name, lien_pdf: f.webViewLink || ('https://drive.google.com/file/d/' + f.id + '/view'), restants_avant_lot: aFaire.length } }));
